import * as Phaser from "phaser";
import { CHARACTER_IDS } from "../data/characters";
import type { Facing } from "../events";

export { CHARACTER_IDS };

// Must match public/assets/sprites/characters.json (generated by scripts/build-assets.ts).
export const CHARACTER_SHEET = "characters";
const COLUMNS = 9;
const DIR_COLUMN: Record<"down" | "up" | "left", number> = { down: 0, up: 3, left: 6 };

const sheetDir = (facing: Facing) => (facing === "right" ? "left" : facing);

export const animKey = (charId: string, action: "idle" | "walk", facing: Facing) =>
  `${charId}:${action}:${sheetDir(facing)}`;

/** Create idle/walk animations for every character once (PreloadScene). */
export function createCharacterAnims(anims: Phaser.Animations.AnimationManager) {
  CHARACTER_IDS.forEach((id, row) => {
    for (const dir of ["down", "up", "left"] as const) {
      const base = row * COLUMNS + DIR_COLUMN[dir];
      anims.create({
        key: animKey(id, "idle", dir),
        frames: [{ key: CHARACTER_SHEET, frame: base }],
      });
      anims.create({
        key: animKey(id, "walk", dir),
        frames: [1, 0, 2, 0].map((f) => ({ key: CHARACTER_SHEET, frame: base + f })),
        frameRate: 8,
        repeat: -1,
      });
    }
  });
}

/** Play the right animation and mirror left-facing frames for "right". */
export function playCharacterAnim(
  sprite: Phaser.GameObjects.Sprite,
  charId: string,
  action: "idle" | "walk",
  facing: Facing,
) {
  sprite.setFlipX(facing === "right");
  sprite.anims.play(animKey(charId, action, facing), true);
}

export function facingFromVector(x: number, y: number, fallback: Facing): Facing {
  if (x === 0 && y === 0) return fallback;
  return Math.abs(x) > Math.abs(y) ? (x > 0 ? "right" : "left") : y > 0 ? "down" : "up";
}

export const FACING_VECTOR: Record<Facing, [number, number]> = {
  up: [0, -1],
  down: [0, 1],
  left: [-1, 0],
  right: [1, 0],
};
